export type ParsedDefinition =
  | { kind: 'ok'; def: RateCardDefinition }
  | { kind: 'invalid'; issues: string[] };

/** Checks a stored or edited definition. String kinds, so TypeScript 7 narrows without strict mode. */
export function parseDefinition(raw: unknown): ParsedDefinition {
  const r = RateCardDefinitionSchema.safeParse(raw);
  if (r.success) return { kind: 'ok', def: r.data };
  return {
    kind: 'invalid',
    issues: r.error.issues.slice(0, 20).map((i) => `${i.path.join('.') || 'definition'}: ${i.message}`),
  };
}

/** The package a service's work goes into (removal, stump, planting...). */
export function packageOf(s: Pick<Service, 'package' | 'category'>): PackageKey {
  if (s.package) return s.package;
  switch (s.category) {
    case 'removal': case 'crane': case 'ground': return 'removal';
    case 'pruning': return 'pruning';
    case 'stump': return 'stump';
    case 'cabling': case 'bracing': case 'props': return 'cabling';
    case 'planting': return 'planting';
    case 'phc': case 'membership': return 'phc';
    default: return 'other';
  }
}
